import numpy as np


def im2col(x, k, stride, pad):
    x = np.asarray(x, dtype=float)
    xp = np.pad(x, ((0, 0), (pad, pad), (pad, pad)))
    c, h, w = xp.shape
    oh, ow = (h - k) // stride + 1, (w - k) // stride + 1
    rows = []
    for i in range(oh):
        for j in range(ow):
            r, q = i * stride, j * stride
            rows.append(xp[:, r:r + k, q:q + k].ravel())
    return np.array(rows)

